#include <QCoreApplication>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QQuickItem>
#include <QDateTime>
#include <QEnterEvent>
#include <QGuiApplication>
#include <QImage>
#include <QImageWriter>
#include <QKeyEvent>
#include <QMouseEvent>
#include <QQmlExtensionPlugin>
#include <QQuickWindow>
#include <qqml.h>

// Nonvisual, temporary reviewer input device. It dispatches manually requested
// events only to the review process's actual window, without global injection.
// No assertions, alternate visual components, automatic verdicts, or QtTest.
class PointerDriver : public QObject {
    Q_OBJECT
public:
    explicit PointerDriver(QObject *parent = nullptr) : QObject(parent) {}

    Q_INVOKABLE QString namedPoint(QObject *root, const QString &name) {
        QJsonObject result;
        auto *item = root ? root->findChild<QQuickItem *>(name) : nullptr;
        result["found"] = item != nullptr;
        if (item) {
            const QPointF point = item->mapToScene(QPointF(item->width()/2, item->height()/2));
            result["x"] = point.x(); result["y"] = point.y();
        }
        return QString::fromUtf8(QJsonDocument(result).toJson(QJsonDocument::Compact));
    }
    Q_INVOKABLE QString scrollInfo(QObject *root) {
        QJsonArray rows;
        if (!root) return QStringLiteral("[]");
        const auto objects = root->findChildren<QObject *>();
        for (QObject *o : objects) {
            const QString cls = QString::fromLatin1(o->metaObject()->className());
            if (!o->inherits("QQuickFlickable") && !cls.contains("ScrollView") && !cls.contains("TextArea")) continue;
            QJsonObject row;
            row["class"] = cls;
            row["objectName"] = o->objectName();
            row["parent"] = o->parent() ? QString::fromLatin1(o->parent()->metaObject()->className()) : QString();
            for (const char *key : {"width", "height", "implicitWidth", "implicitHeight", "contentWidth", "contentHeight", "contentY", "availableWidth", "availableHeight", "visible", "activeFocus", "interactive", "clip"}) {
                const QVariant value = o->property(key);
                if (value.isValid()) row[QString::fromLatin1(key)] = QJsonValue::fromVariant(value);
            }
            if (auto *item = qobject_cast<QQuickItem *>(o)) {
                const QPointF point = item->mapToScene(QPointF());
                row["sceneX"] = point.x(); row["sceneY"] = point.y();
            }
            rows.append(row);
        }
        return QString::fromUtf8(QJsonDocument(rows).toJson(QJsonDocument::Compact));
    }

    Q_INVOKABLE bool capture(QQuickWindow *window, const QString &path) {
        if (!window)
            return false;
        QImageWriter writer(path, "png");
        writer.setCompression(1);
        return writer.write(window->grabWindow());
    }

    Q_INVOKABLE void pointer(QQuickWindow *window, qreal x, qreal y, const QString &kind) {
        if (!window)
            return;
        const QPointF local(x, y);
        const QPointF global(window->mapToGlobal(local.toPoint()));
        QEvent::Type type = QEvent::MouseMove;
        Qt::MouseButton changed = Qt::NoButton;
        if (kind == QStringLiteral("press")) {
            type = QEvent::MouseButtonPress;
            changed = Qt::LeftButton;
            buttons = Qt::LeftButton;
        } else if (kind == QStringLiteral("release")) {
            type = QEvent::MouseButtonRelease;
            changed = Qt::LeftButton;
            buttons = Qt::NoButton;
        }
        if (kind == QStringLiteral("move")) {
            QEnterEvent enter(local, local, global);
            QCoreApplication::sendEvent(window, &enter);
        }
        QMouseEvent event(type, local, local, global, changed, buttons, Qt::NoModifier,
                          Qt::MouseEventSynthesizedByApplication);
        event.setTimestamp(static_cast<quint64>(QDateTime::currentMSecsSinceEpoch()));
        QCoreApplication::sendEvent(window, &event);
        if (x < 0 || y < 0 || x > window->width() || y > window->height()) {
            QEvent leave(QEvent::Leave);
            QCoreApplication::sendEvent(window, &leave);
        }
    }

    Q_INVOKABLE void escape(QQuickWindow *window) {
        if (!window)
            return;
        if (auto *focus = qobject_cast<QQuickWindow *>(QGuiApplication::focusWindow()))
            window = focus;
        QKeyEvent press(QEvent::KeyPress, Qt::Key_Escape, Qt::NoModifier);
        QKeyEvent release(QEvent::KeyRelease, Qt::Key_Escape, Qt::NoModifier);
        QCoreApplication::sendEvent(window, &press);
        QCoreApplication::sendEvent(window, &release);
    }

    Q_INVOKABLE void typeText(QQuickWindow *window, const QString &text) {
        if (!window) return;
        for (const QChar character : text) {
            QKeyEvent press(QEvent::KeyPress, 0, Qt::NoModifier, QString(character));
            QKeyEvent release(QEvent::KeyRelease, 0, Qt::NoModifier, QString(character));
            QCoreApplication::sendEvent(window, &press);
            QCoreApplication::sendEvent(window, &release);
        }
    }

    Q_INVOKABLE void wheel(QQuickWindow *window, qreal x, qreal y, int angleY) {
        if (!window)
            return;
        const QPointF local(x, y);
        const QPointF global(window->mapToGlobal(local.toPoint()));
        QWheelEvent event(local, global, QPoint(), QPoint(0, angleY), Qt::NoButton,
                          Qt::NoModifier, Qt::ScrollUpdate, false,
                          Qt::MouseEventSynthesizedByApplication);
        event.setTimestamp(static_cast<quint64>(QDateTime::currentMSecsSinceEpoch()));
        QCoreApplication::sendEvent(window, &event);
    }
private:
    Qt::MouseButtons buttons = Qt::NoButton;
};

class ReviewInputPlugin : public QQmlExtensionPlugin {
    Q_OBJECT
    Q_PLUGIN_METADATA(IID QQmlExtensionInterface_iid)
public:
    void registerTypes(const char *uri) override {
        qmlRegisterType<PointerDriver>(uri, 1, 0, "PointerDriver");
    }
};

