1	import QtQuick
2	import QtQuick.Window
3	import ReviewInput 1.0
4	import Kos.Ui
5	import "../../../../apps/calendar/qml" as CalendarApp
6	
7	// No visual substitutes or assertions: this is the real Calendar Main root.
8	// The reviewer issues manual commands; QQuickFlickable performs actual motion.
9	CalendarApp.Main {
10	    id: reviewWindow
11	    property int lastReviewCommand: 0
12	    property string nativeRecordPrefix: ""
13	    property double nativeRecordStarted: 0
14	    property int nativeRecordDuration: 4000
15	    property var nativeRecordedFrames: []
16	
17	    PointerDriver { id: pointerDriver }
18	
19	    Timer {
20	        id: nativeRecorder
21	        interval: 50
22	        repeat: true
23	        onTriggered: {
24	            const elapsed = Date.now() - reviewWindow.nativeRecordStarted
25	            if (elapsed > reviewWindow.nativeRecordDuration) {
26	                stop()
27	                console.info("[UIReview] native recording", JSON.stringify({
28	                    prefix: reviewWindow.nativeRecordPrefix,
29	                    requestedInterval: interval,
30	                    duration: elapsed,
31	                    frames: reviewWindow.nativeRecordedFrames
32	                }))
33	                return
34	            }
35	            const index = reviewWindow.nativeRecordedFrames.length
36	            const path = reviewWindow.nativeRecordPrefix + "-" + String(index).padStart(4, "0") + ".png"
37	            const saved = pointerDriver.capture(reviewWindow, path)
38	            reviewWindow.nativeRecordedFrames.push({path: path, elapsedMs: elapsed,
39	                                                   saved: saved, visible: reviewWindow.visible})
40	        }
41	    }
42	
43	    function objectNamed(item, name) {
44	        if (!item)
45	            return null
46	        if (item.objectName === name)
47	            return item
48	        const nodes = item.children || []
49	        for (let n = 0; n < nodes.length; ++n) {
50	            const found = objectNamed(nodes[n], name)
51	            if (found)
52	                return found
53	        }
54	        return null
55	    }
56	
57	    function controlNamed(item, label) {
58	        if (!item || !item.visible)
59	            return null
60	        if (item.hint === label || (item.text === label && typeof item.clicked === "function"))
61	            return item
62	        const nodes = item.children || []
63	        for (let n = 0; n < nodes.length; ++n) {
64	            const found = controlNamed(nodes[n], label)
65	            if (found)
66	                return found
67	        }
68	        return null
69	    }
70	
71	    function timelineIn(item) {
72	        if (!item || !item.visible)
73	            return null
74	        if (typeof item.flick === "function" && item.contentY !== undefined
75	                && item.width > 400 && item.height > 200
76	                && item.contentHeight > item.height + 80)
77	            return item
78	        const nodes = item.children || []
79	        for (let n = 0; n < nodes.length; ++n) {
80	            const found = timelineIn(nodes[n])
81	            if (found)
82	                return found
83	        }
84	        return null
85	    }
86	
87	    function inspectLenses(item) {
88	        if (!item)
89	            return
90	        if (item.lensActive !== undefined && item.lensActive)
91	            console.info("[UIReview] lens rect", String(item.backdropRect),
92	                         "source bounds", item.backdrop.width, item.backdrop.height)
93	        const nodes = item.children || []
94	        for (let n = 0; n < nodes.length; ++n)
95	            inspectLenses(nodes[n])
96	    }
97	
98	    Timer {
99	        interval: 100
100	        repeat: true
101	        running: true
102	        onTriggered: {
103	            const request = new XMLHttpRequest()
104	            request.onreadystatechange = function() {
105	                if (request.readyState !== XMLHttpRequest.DONE)
106	                    return
107	                try {
108	                    const command = JSON.parse(request.responseText)
109	                    if (command.sequence <= reviewWindow.lastReviewCommand)
110	                        return
111	                    reviewWindow.lastReviewCommand = command.sequence
112	                    if (command.action === "nativeRecord") {
113	                        nativeRecorder.stop()
114	                        reviewWindow.nativeRecordPrefix = command.prefix
115	                        reviewWindow.nativeRecordDuration = command.duration || 4000
116	                        reviewWindow.nativeRecordedFrames = []
117	                        nativeRecorder.interval = command.interval || 50
118	                        reviewWindow.nativeRecordStarted = Date.now()
119	                        nativeRecorder.start()
120	                        return
121	                    }
122	                    if (command.action === "captureClient") {
123	                        console.info("[UIReview] native app client capture", command.path,
124	                                     pointerDriver.capture(reviewWindow, command.path))
125	                        return
126	                    }
127	                    if (command.action === "windowWheel") {
128	                        pointerDriver.wheel(reviewWindow, command.x, command.y, command.angleY)
129	                        return
130	                    }
131	                    if (command.action === "pointerObject") {
132	                        const point = JSON.parse(pointerDriver.namedPoint(reviewWindow, command.target))
133	                        console.info("[UIReview] pointerObject", command.target, command.kind, JSON.stringify(point))
134	                        if (point.found) pointerDriver.pointer(reviewWindow, point.x, point.y, command.kind)
135	                        return
136	                    }
137	                    if (command.action === "scrollInfo") {
138	                        console.info("[UIReview] scrollInfo", pointerDriver.scrollInfo(reviewWindow))
139	                        return
140	                    }
141	                    if (command.action === "runtimeInfo") {
142	                        console.info("[UIReview] runtime", JSON.stringify({
143	                            width: reviewWindow.width, height: reviewWindow.height,
144	                            dpr: reviewWindow.Screen.devicePixelRatio,
145	                            appearance: AppTheme.appearanceMode, dark: AppTheme.dark,
146	                            fontFamily: reviewWindow.font.family,
147	                            fontPixelSize: reviewWindow.font.pixelSize
148	                        }))
149	                        return
150	                    }
151	                    if (command.action === "inspectGeometry") {
152	                        const result = []
153	                        for (let n = 0; n < command.names.length; ++n) {
154	                            const item = reviewWindow.objectNamed(reviewWindow.contentItem, command.names[n])
155	                            if (!item) {
156	                                result.push({name: command.names[n], available: false})
157	                                continue
158	                            }
159	                            const point = item.mapToItem(reviewWindow.contentItem, 0, 0)
160	                            result.push({name: command.names[n], width: item.width, height: item.height,
161	                                         x: point.x, y: point.y, visible: item.visible})
162	                        }
163	                        console.info("[UIReview] geometry", JSON.stringify(result))
164	                        return
165	                    }
166	                    if (command.action === "regionWheel" || command.action === "regionPosition") {
167	                        const region = reviewWindow.objectNamed(reviewWindow.contentItem, command.viewport)
168	                        if (!region) {
169	                            console.info("[UIReview] region unavailable", command.viewport)
170	                            return
171	                        }
172	                        const scroll = typeof region.flick === "function" ? region : region.contentItem
173	                        console.info("[UIReview] region", command.viewport, "contentY", scroll.contentY,
174	                                     "height", scroll.height, "contentHeight", scroll.contentHeight)
175	                        if (command.action === "regionWheel") {
176	                            const point = region.mapToItem(reviewWindow.contentItem, region.width / 2, region.height / 2)
177	                            pointerDriver.wheel(reviewWindow, point.x, point.y, command.angleY)
178	                        } else {
179	                            scroll.cancelFlick()
180	                            scroll.contentY = command.contentY
181	                        }
182	                        return
183	                    }
184	                    if (command.action === "pointer") {
185	                        const control = command.target
186	                            ? (reviewWindow.objectNamed(reviewWindow.contentItem, command.target)
187	                               || reviewWindow.controlNamed(reviewWindow.contentItem, command.target)) : null
188	                        const point = control
