import QtQuick
import QtQuick.Window
import ReviewInput 1.0
import Kos.Ui
import "../../../../apps/calendar/qml" as CalendarApp

// No visual substitutes or assertions: this is the real Calendar Main root.
// The reviewer issues manual commands; QQuickFlickable performs actual motion.
CalendarApp.Main {
    id: reviewWindow
    property int lastReviewCommand: 0
    property string nativeRecordPrefix: ""
    property double nativeRecordStarted: 0
    property int nativeRecordDuration: 4000
    property var nativeRecordedFrames: []

    PointerDriver { id: pointerDriver }

    Timer {
        id: nativeRecorder
        interval: 50
        repeat: true
        onTriggered: {
            const elapsed = Date.now() - reviewWindow.nativeRecordStarted
            if (elapsed > reviewWindow.nativeRecordDuration) {
                stop()
                console.info("[UIReview] native recording", JSON.stringify({
                    prefix: reviewWindow.nativeRecordPrefix,
                    requestedInterval: interval,
                    duration: elapsed,
                    frames: reviewWindow.nativeRecordedFrames
                }))
                return
            }
            const index = reviewWindow.nativeRecordedFrames.length
            const path = reviewWindow.nativeRecordPrefix + "-" + String(index).padStart(4, "0") + ".png"
            const saved = pointerDriver.capture(reviewWindow, path)
            reviewWindow.nativeRecordedFrames.push({path: path, elapsedMs: elapsed,
                                                   saved: saved, visible: reviewWindow.visible})
        }
    }

    function objectNamed(item, name) {
        if (!item)
            return null
        if (item.objectName === name)
            return item
        const nodes = item.children || []
        for (let n = 0; n < nodes.length; ++n) {
            const found = objectNamed(nodes[n], name)
            if (found)
                return found
        }
        return null
    }

    function controlNamed(item, label) {
        if (!item || !item.visible)
            return null
        if (item.hint === label || (item.text === label && typeof item.clicked === "function"))
            return item
        const nodes = item.children || []
        for (let n = 0; n < nodes.length; ++n) {
            const found = controlNamed(nodes[n], label)
            if (found)
                return found
        }
        return null
    }

    function timelineIn(item) {
        if (!item || !item.visible)
            return null
        if (typeof item.flick === "function" && item.contentY !== undefined
                && item.width > 400 && item.height > 200
                && item.contentHeight > item.height + 80)
            return item
        const nodes = item.children || []
        for (let n = 0; n < nodes.length; ++n) {
            const found = timelineIn(nodes[n])
            if (found)
                return found
        }
        return null
    }

    function inspectLenses(item) {
        if (!item)
            return
        if (item.lensActive !== undefined && item.lensActive)
            console.info("[UIReview] lens rect", String(item.backdropRect),
                         "source bounds", item.backdrop.width, item.backdrop.height)
        const nodes = item.children || []
        for (let n = 0; n < nodes.length; ++n)
            inspectLenses(nodes[n])
    }

    Timer {
        interval: 100
        repeat: true
        running: true
        onTriggered: {
            const request = new XMLHttpRequest()
            request.onreadystatechange = function() {
                if (request.readyState !== XMLHttpRequest.DONE)
                    return
                try {
                    const command = JSON.parse(request.responseText)
                    if (command.sequence <= reviewWindow.lastReviewCommand)
                        return
                    reviewWindow.lastReviewCommand = command.sequence
                    if (command.action === "nativeRecord") {
                        nativeRecorder.stop()
                        reviewWindow.nativeRecordPrefix = command.prefix
                        reviewWindow.nativeRecordDuration = command.duration || 4000
                        reviewWindow.nativeRecordedFrames = []
                        nativeRecorder.interval = command.interval || 50
                        reviewWindow.nativeRecordStarted = Date.now()
                        nativeRecorder.start()
                        return
                    }
                    if (command.action === "captureClient") {
                        console.info("[UIReview] native app client capture", command.path,
                                     pointerDriver.capture(reviewWindow, command.path))
                        return
                    }
                    if (command.action === "windowWheel") {
                        pointerDriver.wheel(reviewWindow, command.x, command.y, command.angleY)
                        return
                    }
                    if (command.action === "pointerObject") {
                        const point = JSON.parse(pointerDriver.namedPoint(reviewWindow, command.target))
                        console.info("[UIReview] pointerObject", command.target, command.kind, JSON.stringify(point))
                        if (point.found) pointerDriver.pointer(reviewWindow, point.x, point.y, command.kind)
                        return
                    }
                    if (command.action === "scrollInfo") {
                        console.info("[UIReview] scrollInfo", pointerDriver.scrollInfo(reviewWindow))
                        return
                    }
                    if (command.action === "runtimeInfo") {
                        console.info("[UIReview] runtime", JSON.stringify({
                            width: reviewWindow.width, height: reviewWindow.height,
                            dpr: reviewWindow.Screen.devicePixelRatio,
                            appearance: AppTheme.appearanceMode, dark: AppTheme.dark,
                            fontFamily: reviewWindow.font.family,
                            fontPixelSize: reviewWindow.font.pixelSize
                        }))
                        return
                    }
                    if (command.action === "inspectGeometry") {
                        const result = []
                        for (let n = 0; n < command.names.length; ++n) {
                            const item = reviewWindow.objectNamed(reviewWindow.contentItem, command.names[n])
                            if (!item) {
                                result.push({name: command.names[n], available: false})
                                continue
                            }
                            const point = item.mapToItem(reviewWindow.contentItem, 0, 0)
                            result.push({name: command.names[n], width: item.width, height: item.height,
                                         x: point.x, y: point.y, visible: item.visible})
                        }
                        console.info("[UIReview] geometry", JSON.stringify(result))
                        return
                    }
                    if (command.action === "regionWheel" || command.action === "regionPosition") {
                        const region = reviewWindow.objectNamed(reviewWindow.contentItem, command.viewport)
                        if (!region) {
                            console.info("[UIReview] region unavailable", command.viewport)
                            return
                        }
                        const scroll = typeof region.flick === "function" ? region : region.contentItem
                        console.info("[UIReview] region", command.viewport, "contentY", scroll.contentY,
                                     "height", scroll.height, "contentHeight", scroll.contentHeight)
                        if (command.action === "regionWheel") {
                            const point = region.mapToItem(reviewWindow.contentItem, region.width / 2, region.height / 2)
                            pointerDriver.wheel(reviewWindow, point.x, point.y, command.angleY)
                        } else {
                            scroll.cancelFlick()
                            scroll.contentY = command.contentY
                        }
                        return
                    }
                    if (command.action === "pointer") {
                        const control = command.target
                            ? (reviewWindow.objectNamed(reviewWindow.contentItem, command.target)
                               || reviewWindow.controlNamed(reviewWindow.contentItem, command.target)) : null
                        const point = control
                            ? control.mapToItem(reviewWindow.contentItem, control.width / 2, control.height / 2)
                            : Qt.point(Number(command.x), Number(command.y))
                        pointerDriver.pointer(reviewWindow, point.x, point.y, command.kind)
                        console.info("[UIReview] pointer", command.kind, command.target,
                                     point.x, point.y, "hover", control ? control.hovered : "n/a",
                                     "down", control ? control.down : "n/a")
                        return
                    }
                    if (command.action === "typeText") {
                        pointerDriver.typeText(reviewWindow, command.text)
                        const input = objectNamed(reviewWindow.contentItem, "toolbarSearchInput")
                        console.info("[UIReview] textInput", input ? input.text : "missing",
                                     "focus", input ? input.activeFocus : false)
                        return
                    }
                    if (command.action === "escape") {
                        pointerDriver.escape(reviewWindow)
                        return
                    }
                    if (command.action === "resize") {
                        reviewWindow.width = command.width
                        reviewWindow.height = command.height
                        return
                    }
                    if (command.action === "sidebar") {
                        reviewWindow.sidebarExpanded = command.expanded
                        return
                    }
                    if (command.action === "view") {
                        reviewWindow.viewIndex = ["month", "week", "day"].indexOf(command.view)
                        return
                    }
                    if (command.action === "date") {
                        reviewWindow.handleActivation(["--date", command.date], "")
                        return
                    }
                    if (command.action === "openItem") {
                        const entries = reviewWindow.selectedItems || []
                        for (let n = 0; n < entries.length; ++n) {
                            if ((!command.kind || entries[n].kind === command.kind)
                                    && (!command.titleContains || reviewWindow.itemTitle(entries[n]).indexOf(command.titleContains) >= 0)) {
                                reviewWindow.openItem(entries[n])
                                break
                            }
                        }
                        return
                    }
                    if (command.action === "inspect") {
                        reviewWindow.inspectLenses(reviewWindow.contentItem)
                        return
                    }
                    const viewport = reviewWindow.scheduleViewport
                    const timeline = viewport && viewport.contentItem
                            && typeof viewport.contentItem.flick === "function"
                        ? viewport.contentItem
                        : reviewWindow.timelineIn(reviewWindow.contentItem)
                    if (!timeline) {
                        console.info("[UIReview] No visible timeline for manual command")
                        return
                    }
                    console.info("[UIReview] manual", command.action,
                                 "contentY", timeline.contentY,
                                 "width", timeline.width, "height", timeline.height,
                                 "contentHeight", timeline.contentHeight)
                    if (command.action === "wheel") {
                        const point = timeline.mapToItem(reviewWindow.contentItem,
                                                         timeline.width / 2, timeline.height / 2)
                        pointerDriver.wheel(reviewWindow, point.x, point.y, command.angleY)
                    } else if (command.action === "flick") {
                        if (command.cancelFirst)
                            timeline.cancelFlick()
                        timeline.flick(0, command.velocity)
                    } else if (command.action === "stop") {
                        timeline.cancelFlick()
                    } else if (command.action === "position") {
                        timeline.cancelFlick()
                        timeline.contentY = command.contentY
                    }
                } catch (error) {
                    console.info("[UIReview] command unavailable:", String(error))
                }
            }
            request.open("GET", Qt.resolvedUrl("command.json"))
            request.send()
        }
    }
}

